/**
 * Copies Backend/src/contracts/api into src/contracts. The Frontend never imports from ../Backend at build time
 * (the two folders may deploy separately); this copy is the only bridge. Do not edit the copy: a Backend test
 * fails when it drifts from the source.
 *
 *   pnpm sync:contracts
 */
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const from = path.resolve(root, '../Backend/src/contracts/api');
const to = path.resolve(root, 'src/contracts');

export const HEADER =
  '// GENERATED by `pnpm sync:contracts` from Backend/src/contracts/api. DO NOT EDIT: change the Backend and sync.\n';

rmSync(to, { recursive: true, force: true });
mkdirSync(to, { recursive: true });
for (const file of readdirSync(from).filter((f) => f.endsWith('.ts'))) {
  writeFileSync(path.join(to, file), HEADER + readFileSync(path.join(from, file), 'utf8'));
}
console.log(`Synced ${readdirSync(to).length} contract files into src/contracts`);
